    private Player chooseBalancedPlayer(){
        ArrayList<Player> candidates=new ArrayList<>();
        if(players.size()>=4){if(selectionBag.isEmpty()){for(Player p:players)selectionBag.add(p.id);Collections.shuffle(selectionBag);}for(String id:selectionBag)if(!id.equals(lastPlayerId))for(Player p:players)if(p.id.equals(id))candidates.add(p);if(candidates.isEmpty()){selectionBag.clear();return chooseBalancedPlayer();}}
        else for(Player p:players)if(!p.id.equals(lastPlayerId))candidates.add(p);
        if(candidates.isEmpty())candidates.addAll(players);Player chosen=candidates.get(random.nextInt(candidates.size()));lastPlayerId=chosen.id;selectionBag.remove(chosen.id);if(players.size()>=4&&selectionBag.isEmpty())round++;return chosen;
    }

