    @Override public void onBackPressed(){handleAppBack();}private void handleAppBack(){if(currentScreen==1||currentScreen==5){showHome();return;}if(currentScreen==2){showSettings();return;}if(currentScreen!=0){showHome();return;}super.onBackPressed();}
    private void connectBilling(){
        if(billingClient!=null&&billingClient.isReady()){queryProduct();refreshPurchases();return;}
        if(billingClient!=null)billingClient.endConnection();
        PendingPurchasesParams pending=PendingPurchasesParams.newBuilder().enableOneTimeProducts().build();
        billingClient=BillingClient.newBuilder(this).setListener(this::onPurchasesUpdated).enablePendingPurchases(pending).enableAutoServiceReconnection().build();
        billingClient.startConnection(new BillingClientStateListener(){public void onBillingSetupFinished(BillingResult r){if(r.getResponseCode()==BillingClient.BillingResponseCode.OK){purchaseConnectAttempts=0;queryProduct();refreshPurchases();}else if(pendingPurchaseLaunch)retryPurchaseConnection("Google Play is unavailable: "+r.getDebugMessage());}public void onBillingServiceDisconnected(){if(pendingPurchaseLaunch)retryPurchaseConnection("Google Play connection was lost.");}});
    }
    private void queryProduct(){
        if(billingClient==null||!billingClient.isReady())return;
        QueryProductDetailsParams.Product p=QueryProductDetailsParams.Product.newBuilder().setProductId(PRODUCT_ID).setProductType(BillingClient.ProductType.INAPP).build();
        billingClient.queryProductDetailsAsync(QueryProductDetailsParams.newBuilder().setProductList(Collections.singletonList(p)).build(),(r,list)->{
            premiumProduct=null;
            if(r.getResponseCode()==BillingClient.BillingResponseCode.OK&&list!=null)for(ProductDetails d:list.getProductDetailsList())if(PRODUCT_ID.equals(d.getProductId())){premiumProduct=d;ProductDetails.OneTimePurchaseOfferDetails o=d.getOneTimePurchaseOfferDetails();if(o!=null)premiumPrice=o.getFormattedPrice();break;}
            if(pendingPurchaseLaunch){if(premiumProduct!=null)launchReadyPurchase();else {pendingPurchaseLaunch=false;toast("Premium Levels is not available from Google Play yet. Confirm product 'premium_levels' is active and this build is installed from a testing track.");}}
        });
    }
    private void launchPurchase(){pendingPurchaseLaunch=true;purchaseConnectAttempts=0;if(billingClient==null||!billingClient.isReady()){toast("Connecting to Google Play…");connectBilling();return;}if(premiumProduct==null){toast("Loading Premium Levels…");queryProduct();return;}launchReadyPurchase();}
    private void retryPurchaseConnection(String message){if(++purchaseConnectAttempts>2){pendingPurchaseLaunch=false;toast(message);return;}handler.postDelayed(()->connectBilling(),700);}
    private void launchReadyPurchase(){
        if(!pendingPurchaseLaunch||premiumProduct==null)return;
        ProductDetails.OneTimePurchaseOfferDetails o=premiumProduct.getOneTimePurchaseOfferDetails();
        if(o==null){pendingPurchaseLaunch=false;toast("Premium Levels has no active Google Play offer.");return;}
        BillingFlowParams.ProductDetailsParams item=BillingFlowParams.ProductDetailsParams.newBuilder().setProductDetails(premiumProduct).setOfferToken(o.getOfferToken()).build();
        BillingResult result=billingClient.launchBillingFlow(this,BillingFlowParams.newBuilder().setProductDetailsParamsList(Collections.singletonList(item)).build());
        pendingPurchaseLaunch=false;if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK)toast("Could not open checkout: "+result.getDebugMessage());
    }
    private void refreshPurchases(){if(billingClient==null||!billingClient.isReady())return;billingClient.queryPurchasesAsync(QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build(),(r,purchases)->{if(r.getResponseCode()!=0)return;boolean found=false;for(Purchase p:purchases)if(p.getProducts().contains(PRODUCT_ID)&&p.getPurchaseState()==Purchase.PurchaseState.PURCHASED){found=true;processPurchase(p);}setEntitlement(found);});}    private void restorePurchase(){
        if(billingClient==null||!billingClient.isReady()){
            toast("Connecting to Google Play…");connectBilling();
            handler.postDelayed(()->{if(billingClient!=null&&billingClient.isReady())restorePurchase();else toast("Google Play is not available yet. Try again shortly.");},1200);
            return;
        }
        toast("Checking your Google Play purchases…");
        billingClient.queryPurchasesAsync(QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build(),(result,purchases)->{
            if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK){toast("Could not check purchases. Please try again.");return;}
            for(Purchase purchase:purchases)if(purchase.getProducts().contains(PRODUCT_ID)&&purchase.getPurchaseState()==Purchase.PurchaseState.PURCHASED){processPurchase(purchase);toast("Premium levels restored.");return;}
            toast("No Premium Levels purchase was found for this Google Play account.");
        });
    }
    private void onPurchasesUpdated(BillingResult r,List<Purchase> purchases){if(r.getResponseCode()==0&&purchases!=null)for(Purchase p:purchases)processPurchase(p);}
    private void processPurchase(Purchase p){if(!p.getProducts().contains(PRODUCT_ID)||p.getPurchaseState()!=Purchase.PurchaseState.PURCHASED)return;setEntitlement(true);if(!p.isAcknowledged())billingClient.acknowledgePurchase(AcknowledgePurchaseParams.newBuilder().setPurchaseToken(p.getPurchaseToken()).build(),x->{});}
    private void setEntitlement(boolean owned){entitlement=owned;prefs().edit().putBoolean("premium_owned",owned).apply();runOnUiThread(()->showHome());}

    private String themeMode(){return prefs().getString("theme_mode","system");}private boolean isDarkTheme(){return "dark".equals(themeMode())||("system".equals(themeMode())&&((getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES));}private boolean systemPaletteEnabled(){return Build.VERSION.SDK_INT>=Build.VERSION_CODES.S&&prefs().getBoolean("use_system_palette",false);}
    private void applyTheme(){boolean dark=isDarkTheme();if(dark){INK=Color.rgb(23,19,38);PANEL=Color.rgb(34,28,49);PURPLE=Color.rgb(63,47,88);PINK=Color.rgb(255,128,160);TEXT=Color.rgb(255,249,239);MUTED=Color.rgb(187,180,206);OUTLINE=Color.rgb(61,54,79);}else{INK=Color.rgb(250,247,255);PANEL=Color.rgb(255,255,255);PURPLE=Color.rgb(132,101,195);PINK=Color.rgb(224,79,120);TEXT=Color.rgb(35,27,51);MUTED=Color.rgb(99,88,120);OUTLINE=Color.rgb(220,212,233);}if(systemPaletteEnabled()){if(dark){INK=getColor(android.R.color.system_neutral1_900);PANEL=getColor(android.R.color.system_neutral1_800);PURPLE=getColor(android.R.color.system_accent1_200);PINK=getColor(android.R.color.system_accent2_200);TEXT=getColor(android.R.color.system_neutral1_10);MUTED=getColor(android.R.color.system_neutral2_200);OUTLINE=getColor(android.R.color.system_neutral2_600);}else{INK=getColor(android.R.color.system_neutral1_10);PANEL=getColor(android.R.color.system_neutral1_0);PURPLE=getColor(android.R.color.system_accent1_600);PINK=getColor(android.R.color.system_accent2_600);TEXT=getColor(android.R.color.system_neutral1_900);MUTED=getColor(android.R.color.system_neutral2_600);OUTLINE=getColor(android.R.color.system_neutral2_300);}}if(root!=null)root.setBackgroundColor(INK);WindowInsetsControllerCompat bars=WindowCompat.getInsetsController(getWindow(),root==null?getWindow().getDecorView():root);if(bars!=null){bars.setAppearanceLightStatusBars(!dark);bars.setAppearanceLightNavigationBars(!dark);}}

    private SharedPreferences prefs(){return getSharedPreferences("truth_or_dare_native",MODE_PRIVATE);}private void saveState(){try{JSONObject o=new JSONObject();o.put("level",level);JSONArray ps=new JSONArray();for(Player p:players)ps.put(p.json());o.put("players",ps);JSONArray cards=new JSONArray();for(Card c:customCards)cards.put(c.json());o.put("cards",cards);JSONObject orders=new JSONObject();for(String k:deckOrders.keySet())orders.put(k,new JSONArray(deckOrders.get(k)));o.put("orders",orders);prefs().edit().putString("state",o.toString()).apply();}catch(Exception ignored){}}
    private void loadState(){try{JSONObject o=new JSONObject(prefs().getString("state","{}"));level=o.optString("level","soft");JSONArray ps=o.optJSONArray("players");if(ps!=null)for(int i=0;i<ps.length();i++)players.add(new Player(ps.getJSONObject(i)));JSONArray cards=o.optJSONArray("cards");if(cards!=null)for(int i=0;i<cards.length();i++)customCards.add(new Card(cards.getJSONObject(i)));JSONObject orders=o.optJSONObject("orders");if(orders!=null)for(Iterator<String> it=orders.keys();it.hasNext();){String k=it.next();JSONArray a=orders.getJSONArray(k);ArrayList<Integer> v=new ArrayList<>();for(int i=0;i<a.length();i++)v.add(a.getInt(i));deckOrders.put(k,v);}}catch(Exception ignored){}}
    private SpannableString coloredPrompt(String raw,String activeName,String targetName){SpannableString styled=new SpannableString(raw);int activeStart=raw.indexOf(activeName);if(activeStart>=0)styled.setSpan(new ForegroundColorSpan(primaryActionColor()),activeStart,activeStart+activeName.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);if(targetName!=null){int targetStart=raw.indexOf(targetName,activeStart+activeName.length());if(targetStart>=0)styled.setSpan(new ForegroundColorSpan(primaryActionColor()),targetStart,targetStart+targetName.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}return styled;}
    private int timedDareSeconds(String prompt){if(prompt==null)return 0;java.util.regex.Matcher m=java.util.regex.Pattern.compile("(\\d+)\\s*seconds?",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(prompt);if(m.find())try{return Integer.parseInt(m.group(1));}catch(Exception ignored){}return prompt.toLowerCase(Locale.US).contains("while answering")?30:0;}
