        private final ArrayList<String> names;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final int panel,text,outline;private float bottleAngle=0f;
        BottleWheelView(android.content.Context context,ArrayList<String> playerNames,int panelColor,int textColor,int outlineColor,int accentColor){super(context);names=playerNames;panel=panelColor;text=textColor;outline=outlineColor;setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
