        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float size=Math.min(getWidth(),getHeight());float cx=getWidth()/2f,cy=getHeight()/2f,r=size/2f-dp(5);paint.setStyle(Paint.Style.FILL);int[] colors={Color.rgb(243,138,168),Color.rgb(174,230,208),Color.rgb(188,170,247),Color.rgb(143,114,209),Color.rgb(121,220,198),Color.rgb(255,211,106)};float step=360f/Math.max(1,names.size());RectF oval=new RectF(cx-r,cy-r,cx+r,cy+r);for(int i=0;i<names.size();i++){paint.setColor(colors[i%colors.length]);canvas.drawArc(oval,-90+i*step,step,true,paint);}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));paint.setColor(outline);canvas.drawCircle(cx,cy,r,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(text);paint.setTextSize(dp(names.size()>6?11:13));paint.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);paint.setTextAlign(Paint.Align.CENTER);for(int i=0;i<names.size();i++){double angle=Math.toRadians(-90+i*step+step/2f);float x=cx+(float)Math.cos(angle)*r*.68f;float y=cy+(float)Math.sin(angle)*r*.68f-(paint.ascent()+paint.descent())/2f;canvas.drawText(names.get(i),x,y,paint);}canvas.save();canvas.rotate(bottleAngle,cx,cy);paint.setColor(Color.rgb(73,35,12));canvas.drawRoundRect(new RectF(cx-dp(14),cy-r*.34f,cx+dp(14),cy+r*.15f),dp(18),dp(18),paint);paint.setColor(Color.rgb(133,67,20));canvas.drawRoundRect(new RectF(cx-dp(11),cy-r*.32f,cx+dp(11),cy+r*.13f),dp(14),dp(14),paint);paint.setColor(Color.rgb(117,57,16));canvas.drawRoundRect(new RectF(cx-dp(6),cy-r*.45f,cx+dp(6),cy-r*.28f),dp(5),dp(5),paint);paint.setColor(Color.rgb(42,27,20));canvas.drawRoundRect(new RectF(cx-dp(7),cy-r*.49f,cx+dp(7),cy-r*.44f),dp(3),dp(3),paint);paint.setColor(Color.argb(125,255,239,205));canvas.drawRoundRect(new RectF(cx-dp(6),cy-r*.28f,cx-dp(3),cy+r*.01f),dp(3),dp(3),paint);paint.setColor(panel);canvas.drawCircle(cx,cy+r*.10f,dp(4),paint);canvas.restore();}
